								A[state + idx<'i'>(1)] - two * center +
								A[state - idx<'i'>(1)];
							num_t lap_j =
								A[state + idx<'j'>(1)] - two * center +
								A[state - idx<'j'>(1)];
							num_t lap_k =
								A[state + idx<'k'>(1)] - two * center +
								A[state - idx<'k'>(1)];

							// Same formula as original code:
							//   B = center
							//     + 0.125 * lap_i
							//     + 0.125 * lap_j
							//     + 0.125 * lap_k
							B[state] = center
								+ c * lap_i
