[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Interior region: i, j, k in [1, n-2]
	// This matches the original code, which never updates the boundary layer.
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Tunable tile sizes in the outer spatial dimensions.
	// We block only i and j:
	//   - improves cache locality in the i–j plane
	//   - leaves k as the innermost contiguous dimension for vectorization
	constexpr auto tile_i = noarr::lit<16>; // tile size in i
	constexpr auto tile_j = noarr::lit<16>; // tile size in j

