	//   into_blocks_dynamic<'i','I','i','r'>(tile_i)
	//     - replaces dimension 'i' with:
	//         'I' : block index in i
	//         'i' : intra-block index in i
	//         'r' : "present" flag dimension; empty for out-of-range elements
	//   likewise for j with ('J','j','s').
	//
	// We then hoist I and J so that the effective traversal order per time step is:
	//   for I (tile in i)
	//     for J (tile in j)
	//       for i, j, k in tile(I,J)
	// which improves spatial locality while preserving the original layout.
	auto blocking =
		noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(tile_i) ^
		noarr::into_blocks_dynamic<'j', 'J', 'j', 's'>(tile_j) ^
		noarr::hoist<'I'>() ^
		noarr::hoist<'J'>();

