		.template for_dims<'t'>([=](auto t_trav) {
			// t_trav has 't' fixed for this time step; we ignore 't' when
			// indexing A and B. We now apply the interior restriction and the
			// spatial blocking only inside this time step.
			auto inner = t_trav.order(interior ^ blocking);

			// -----------------------------------------------------------------
			// First sweep: update B from A on the interior points.
			// With blocking applied, the effective traversal is:
			//   for I, J: tiles in i and j (outer, thanks to hoist)
			//     for i, j, k: interior points in tile (I, J)
			// and 'state' always carries global indices 'i', 'j', 'k' that can
			// be used directly on A and B, including neighbor accesses.
			// -----------------------------------------------------------------
			inner.for_each([=](auto state) {
				using noarr::idx;

				// state contains 'i', 'j', 'k', and 't' (ignored by A/B)
				num_t center = A[state];

				num_t lap_i = A[state + idx<'i'>(1)] - two * center + A[state - idx<'i'>(1)];
