				num_t lap_k = A[state + idx<'k'>(1)] - two * center + A[state - idx<'k'>(1)];

				// Same arithmetic as original:
				//   B = 0.125 * lap_i + 0.125 * lap_j + 0.125 * lap_k + center
				B[state] = c * lap_i
				         + c * lap_j
				         + c * lap_k
				         + center;
			});

			// -----------------------------------------------------------------
			// Second sweep: update A from B on the same interior region.
			// Traversal order is identical to the first sweep, so B values
			// just produced for a tile are reused from cache by the A update.
			// -----------------------------------------------------------------
			inner.for_each([=](auto state) {
				using noarr::idx;

				num_t center = B[state];

				num_t lap_i = B[state + idx<'i'>(1)] - two * center + B[state - idx<'i'>(1)];
				num_t lap_j = B[state + idx<'j'>(1)] - two * center + B[state - idx<'j'>(1)];
				num_t lap_k = B[state + idx<'k'>(1)] - two * center + B[state - idx<'k'>(1)];

