	using namespace noarr;

	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		// Original: A[i][j][k] = B[i][j][k] =
		//   (DATA_TYPE) (i + j + (n - k)) * 10 / n;
		num_t value = num_t((i + j + (n - k)) * 10) / num_t(n);

		A[state] = value;
		B[state] = value;
	});
}

// computation kernel
//
// Optimized for:
//   - 3D spatial blocking (tiling) in i, j, k for cache locality,
//   - preserving unit‑stride access and SIMD‑friendly innermost k loop,
//   - keeping the original two-sweep, double-buffered semantics:
//
//     for t:
//       B = stencil(A)
//       A = stencil(B)
//
// All loop nests (including time) are expressed via Noarr traversers.
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	// A, B: i x j x k
	using namespace noarr;

	// Interior region: i, j, k in [1, n-2]
	// (boundary values i,j,k ∈ {0, n-1} stay fixed)
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times.
	// We only use 't' to drive the outermost loop; A and B ignore 't'.
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	// ---------------------------------------------------------------------
	// 3D spatial blocking:
	//
	// We tile the interior domain in all three spatial dimensions. The
	// tiles are defined via into_blocks_dynamic so that non-multiples of the
	// tile size are handled correctly by an extra "presence" dimension.
	//
	//   'I', 'J', 'K' : tile indices in i, j, k
	//   'g', 'h', 'l' : guard dimensions (presence flags) for i, j, k
	//
	// The guard dimensions ensure that iterations that would step outside
	// the [1, n-2] interior are automatically skipped by the traverser.
	//
	// Tile sizes are chosen to give reasonable cache locality while
	// keeping k-tiles large enough for SIMD/vectorization.
	// ---------------------------------------------------------------------
	constexpr std::size_t tile_i = 8;   // tile size along i (outermost spatial dim)
	constexpr std::size_t tile_j = 8;   // tile size along j
	constexpr std::size_t tile_k = 32;  // tile size along k (contiguous dim)

	using noarr::lit;

	auto spatial_tiling =
		interior
		// split i into tiles: I (tile index), i (intra-tile index), g (guard)
		^ noarr::into_blocks_dynamic<'i', 'I', 'i', 'g'>(lit<tile_i>)
		// split j into tiles: J (tile index), j (intra-tile index), h (guard)
		^ noarr::into_blocks_dynamic<'j', 'J', 'j', 'h'>(lit<tile_j>)
		// split k into tiles: K (tile index), k (intra-tile index), l (guard)
		^ noarr::into_blocks_dynamic<'k', 'K', 'k', 'l'>(lit<tile_k>)
		// hoist tile indices so the traversal order is:
		//   t -> I -> J -> K -> (i, j, k inside the tile)
		^ noarr::hoist<'I'>()
		^ noarr::hoist<'J'>()
		^ noarr::hoist<'K'>();

	// Precompute constants once; these are reused at all stencil points.
	const num_t coef = num_t(0.125);
	const num_t two  = num_t(2.0);

	#pragma scop
	noarr::traverser(A, B)
		// 4D view: time (t) x interior(i,j,k), then tiled into (I,J,K)
		.order(time_bcast ^ spatial_tiling)
		// Outer sequential loop over time steps
		.template for_dims<'t'>([=](auto t_trav) {
			// -----------------------------------------------------------------
			// First sweep: update B from A on the interior.
			// We iterate tiles in (I, J, K), then all points in each tile.
			// -----------------------------------------------------------------
			t_trav.template for_dims<'I', 'J', 'K'>([=](auto tile_trav) {
				// Fix i & j (and their guards) for this tile; the remaining
				// free dimensions are k (and its guard), which for_each will
				// iterate with k as the innermost, unit-stride loop.
				tile_trav.template for_dims<'i', 'g', 'j', 'h'>([=](auto line_trav) {
					line_trav.for_each([=](auto state) {
						using noarr::idx;

						// state contains 'i', 'j', 'k' (and implicitly time t),
						// all restricted to the interior due to the slicing
						// and the guard dimensions.

						const num_t center = A[state];
						const num_t two_center = two * center;

						const num_t lap_i =
							A[state + idx<'i'>(1)] - two_center + A[state - idx<'i'>(1)];
						const num_t lap_j =
							A[state + idx<'j'>(1)] - two_center + A[state - idx<'j'>(1)];
						const num_t lap_k =
							A[state + idx<'k'>(1)] - two_center + A[state - idx<'k'>(1)];

						// Same formula as the original kernel, but with
						// precomputed constants to reduce redundant work.
						B[state] = center
						         + coef * lap_i
						         + coef * lap_j
						         + coef * lap_k;
					});
				});
			});

			// -----------------------------------------------------------------
			// Second sweep: update A from B on the interior.
			// Entire B-sweep for this t is completed above before any A-sweep
			// starts, preserving the original step ordering.
			// -----------------------------------------------------------------
			t_trav.template for_dims<'I', 'J', 'K'>([=](auto tile_trav) {
				tile_trav.template for_dims<'i', 'g', 'j', 'h'>([=](auto line_trav) {
					line_trav.for_each([=](auto state) {
						using noarr::idx;

						const num_t center = B[state];
						const num_t two_center = two * center;

						const num_t lap_i =
							B[state + idx<'i'>(1)] - two_center + B[state - idx<'i'>(1)];
						const num_t lap_j =
							B[state + idx<'j'>(1)] - two_center + B[state - idx<'j'>(1)];
						const num_t lap_k =
							B[state + idx<'k'>(1)] - two_center + B[state - idx<'k'>(1)];

						A[state] = center
						         + coef * lap_i
						         + coef * lap_j
						         + coef * lap_k;
					});
				});
			});
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	int n = N;
	int tsteps = TSTEPS;

	// set lengths for spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
